sha=lambda p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest();hashes={p:sha(p) for p in files};started=time.perf_counter();suite=unittest.defaultTestLoader.loadTestsFromNames(modules);assert suite.countTestCases()==11
result=unittest.TextTestRunner(verbosity=2,failfast=True).run(suite);assert hashes=={p:sha(p) for p in files}
